     [
      "t4-504",
      "Hyperpituitarism och hypopituitarism",
      "Central hypotyreos som del av hypofysinsufficiens."
     ],
     [
      "t4-494",
      "Tyreoiditer",
      "Hypotyreoid fas efter subakut/post partum-tyreoidit, oftast övergående."
     ],
     [
      "",
      "Depression",
      "Liknande symtom men normalt TSH."
     ]
